import java.util.*;
public class Main {
    public static boolean isNumber(String s) {
        boolean seenDigit = false, seenExponent = false, seenDot = false;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isDigit(c)) seenDigit = true;
            else if (c == '+' || c == '-') {
                if (i > 0 && s.charAt(i-1) != 'e' && s.charAt(i-1) != 'E') return false;
            } else if (c == 'e' || c == 'E') {
                if (seenExponent || !seenDigit) return false;
                seenExponent = true;
                seenDigit = false;
            } else if (c == '.') {
                if (seenDot || seenExponent) return false;
                seenDot = true;
            } else return false;
        }
        return seenDigit;
    }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNext()) return;
        String s = sc.next();
        if (s.startsWith("\"") && s.endsWith("\"")) s = s.substring(1, s.length() - 1);
        System.out.println(isNumber(s) ? "true" : "false");
    }
}

